export const etfTrackingDefinitions={
  etfTrackingPlanning:{title:'Compare matched hypothetical NAV and benchmark returns',fields:[
    ['trackingPrincipal','Opening amount in both comparisons (CAD)',10000,100,1000000,1000],
    ['trackingIndex','Assumed benchmark annual total return (%)',8,-20,20,1],
    ['trackingGap','Fund annual return minus benchmark (percentage points)',-.28,-2,2,.01],
    ['trackingYears','Whole years repeating the same annual return gap',10,1,30,1]
  ]}
};
export const trackingMonthlySample={fundA:[-.0002,-.0002,-.0002,-.0002],fundB:[.001,-.0014,.001,-.0014]};
export const trackingAttribution=[
  {label:'Operating expenses',value:-.0015},
  {label:'Portfolio trading',value:-.0006},
  {label:'Unrecovered taxes',value:-.0008},
  {label:'Net lending revenue',value:.0003},
  {label:'Other implementation effects',value:-.0002}
];
export function trackingWealth(input,years=input.trackingYears){
  const indexRate=input.trackingIndex/100,fundRate=indexRate+input.trackingGap/100,index=input.trackingPrincipal*(1+indexRate)**years,fund=input.trackingPrincipal*(1+fundRate)**years;
  return {indexRate,fundRate,index,fund,difference:fund-index,cumulativeGap:(1+fundRate)**years-(1+indexRate)**years};
}
export function etfTrackingResult(kind,input){
  if(kind!=='etfTrackingPlanning')throw Error('Unknown ETF tracking topic.');
  const p=trackingWealth(input),horizons=[...new Set([1,5,10,20,30,input.trackingYears])].sort((a,b)=>a-b),path=Array.from({length:input.trackingYears+1},(_,x)=>({x,...trackingWealth(input,x)}));
  return {metrics:[['Ending hypothetical fund NAV wealth',p.fund,'money'],['Fund minus benchmark ending wealth',p.difference,'money'],['Repeated annual fund-minus-benchmark return gap',input.trackingGap/100,'pp']],note:'All fund names, benchmark returns, return gaps and attribution entries are invented. The fund and benchmark use the same opening CAD value, dates, currency and total-return basis with distributions reinvested. The annual fund NAV return equals the benchmark assumption plus the entered percentage-point gap, which can have either sign. It is already net of any costs reflected in that assumed NAV return: no second expense-ratio deduction is made. Annual factors repeat without contributions, withdrawals or probabilities. The benchmark wealth line is a calculation reference, not a directly purchasable investment. No investor tax, brokerage charges, spread, premium/discount or FX conversion is included. The separate four-month sample and attribution bridge remain fixed original illustrations; they do not generate the selected annual gap. These figures do not estimate a real fund’s tracking error or future performance.',charts:[
    {id:'etf-tracking-matched-wealth',type:'line',title:'Match the currency, dates and return definition before comparing wealth',unit:'money',xLabel:'Complete years of the repeated annual scenario',series:[{name:'Hypothetical fund NAV total-return wealth',rows:path.map(r=>({x:r.x,value:r.fund}))},{name:'Matching benchmark total-return reference',dash:true,rows:path.map(r=>({x:r.x,value:r.index}))}],note:'Both calculations start with the same CAD amount. Fund return is '+(p.fundRate*100).toFixed(2)+'% per year and benchmark return is '+input.trackingIndex.toFixed(2)+'% per year in this selected scenario. The difference is already embedded in the two growth factors. These are nominal annual endpoints, not actual NAV observations, a tracking-error estimate or an account-level return.'},
    {id:'etf-tracking-cumulative-gap',type:'signedbar',title:'A cumulative return gap has a different horizon from an annual gap',unit:'pp',tableUnit:'percentage points',unitLabel:'Cumulative fund total return minus benchmark total return · percentage points',rows:horizons.map(years=>({label:years+' '+(years===1?'year':'years')+(years===input.trackingYears?' · selected horizon':''),value:trackingWealth(input,years).cumulativeGap})),note:'Every row begins with the same opening snapshot and repeats the entered annual assumptions for its own labeled horizon. Each difference is [(1 + fund annual return)^years − 1] minus [(1 + benchmark annual return)^years − 1]. It is a percentage-point difference between two cumulative returns, not an annual expense ratio, relative wealth ratio or estimate of tracking error. Negative means the fund ends below the benchmark; positive means above. Dividing a cumulative gap by the number of years does not recover the annual tracking difference.'},
    {id:'etf-tracking-monthly-pattern',type:'line',title:'The same mean monthly gap can hide different month-to-month patterns',unit:'pp',tableUnit:'percentage points',unitLabel:'Four invented monthly fund-minus-benchmark return differences · percentage points',xLabel:'Month in the separate fixed sample',xMin:1,xTicks:[1,2,3,4].map(value=>({value,label:value})),series:[{name:'Fund A · constant monthly gap',rows:trackingMonthlySample.fundA.map((value,i)=>({x:i+1,value}))},{name:'Fund B · varying monthly gap',dash:true,rows:trackingMonthlySample.fundB.map((value,i)=>({x:i+1,value}))}],note:'Both four-month arithmetic mean gaps equal −0.02 percentage points per month. Fund A is constant; Fund B alternates +0.10 and −0.14 percentage points. The annual-gap control does not alter this separate fixed sample. Four observations are not adequate history for a useful real tracking-error estimate. This figure supplies active-return differences, not complete fund and benchmark return series; it does not calculate their cumulative wealth or extrapolate an annualized statistic.'},
    {id:'etf-tracking-invented-attribution',type:'waterfall',title:'Use a signed reconciliation without pretending the components were measured',unit:'pp',tableUnit:'percentage points',unitLabel:'Separate invented one-year fund-minus-benchmark attribution · percentage points',rows:trackingAttribution.map(r=>({...r})),totalLabel:'Illustrated one-year tracking difference',note:'These fixed entries sum to −0.28 percentage points, matching the original worked article example. They remain unchanged if the selected annual-gap control changes. No actual fund, fee schedule, tax recovery or lending revenue has been observed. The operating-expense entry is a component of the illustrated return gap, not another deduction from the NAV wealth path. In real analysis, distinguish disclosed measurements from modeled explanations and unexplained residuals.'}
  ]};
}
